content:
:root {
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --border-color: #e2e8f0;
  --success-color: #10b981;
  --danger-color: #ef4444;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.dashboard-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px;
}

.header {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 24px;
}

@media (min-width: 768px) {
  .header {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.title {
  font-size: 24px;
  font-weight: 700;
  color: var(--text-main);
}

.filter-buttons {
  display: flex;
  gap: 8px;
  background: var(--card-bg);
  padding: 4px;
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}

.btn {
  background: transparent;
  border: none;
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-muted);
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn:hover {
  color: var(--text-main);
  background-color: var(--bg-color);
}

.btn-active {
  background-color: var(--primary-color);
  color: #ffffff;
}

.btn-active:hover {
  background-color: var(--primary-hover);
  color: #ffffff;
}

.card-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
  margin-bottom: 24px;
}

@media (min-width: 640px) {
  .card-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .card-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.metric-card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.card-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-muted);
}

.card-value {
  font-size: 28px;
  font-weight: 700;
  color: var(--text-main);
}

.card-trend {
  font-size: 13px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 4px;
}

.card-trend.positive {
  color: var(--success-color);
}

.card-trend.negative {
  color: var(--danger-color);
}

.chart-section {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
}

.chart-title {
  font-size: 18px;
  font-weight: 600;
  color: var(--text-main);
  margin-bottom: 20px;
}

export interface MonthlyData {
  month: string;
  sales: number;
  customers: number;
  avgPrice: number;
}

export interface MetricData {
  title: string;
  value: string;
  trend: string;
  isPositive: boolean;
}

import { MetricData } from '../types';
import '../index.css';

interface MetricCardProps extends MetricData {}

export default function MetricCard({ title, value, trend, isPositive }: MetricCardProps) {
  return (
    <div className="metric-card">
      <div className="card-title">{title}</div>
      <div className="card-value">{value}</div>
      <div className={`card-trend ${isPositive ? 'positive' : 'negative'}`}>
        {trend}
      </div>
    </div>
  );
}

import { MonthlyData } from '../types';
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid } from 'recharts';
import '../index.css';

interface SalesChartProps {
  data?: MonthlyData[];
}

export default function SalesChart({ data = [] }: SalesChartProps) {
  return (
    <div className="chart-section">
      <h2 className="chart-title">月別売上推移</h2>
      <div style={{ width: '100%, height: 320px', minHeight: '300px' }}>
        <ResponsiveContainer width="100%" height={300}>
          <BarChart data={data}>
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
            <XAxis dataKey="month" stroke="#64748b" fontSize={12} />
            <YAxis stroke="#64748b" fontSize={12} tickFormatter={(value) => `¥${value.toLocaleString()}`} />
            <Tooltip 
              formatter={(value: number) => [`¥${value.toLocaleString()}`, '売上']}
              contentStyle={{ backgroundColor: '#ffffff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }}
            />
            <Bar dataKey="sales" fill="#3b82f6" radius={[6, 6, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { MonthlyData } from './types';
import MetricCard from './components/MetricCard';
import SalesChart from './components/SalesChart';
import './index.css';

const monthlyDataList: MonthlyData[] = [
  { month: '1月', sales: 1250000, customers: 410, avgPrice: 3048 },
  { month: '2月', sales: 1100000, customers: 380, avgPrice: 2894 },
  { month: '3月', sales: 1420000, customers: 450, avgPrice: 3155 },
  { month: '4月', sales: 1380000, customers: 430, avgPrice: 3209 },
  { month: '5月', sales: 1550000, customers: 490, avgPrice: 3163 },
  { month: '6月', sales: 1680000, customers: 520, avgPrice: 3230 },
];

export default function App() {
  const [filter, setFilter] = useState<'all' | 'Q1' | 'Q2'>('all');

  const filteredData = monthlyDataList.filter((item) => {
    if (filter === 'Q1') return ['1月', '2月', '3月'].includes(item.month);
    if (filter === 'Q2') return ['4月', '5月', '6月'].includes(item.month);
    return true;
  });

  // 合計または平均の計算
  const totalSales = filteredData.reduce((sum, item) => sum + item.sales, 0);
  const totalCustomers = filteredData.reduce((sum, item) => sum + item.customers, 0);
  const avgUnitPrice = Math.round(
    filteredData.reduce((sum, item) => sum + item.avgPrice, 0) / (filteredData.length || 1)
  );

  return (
    <div className="dashboard-container">
      <header className="header">
        <h1 className="title">売上ダッシュボード</h1>
        <div className="filter-buttons">
          <button
            className={`btn ${filter === 'all' ? 'btn-active' : ''}`}
            onClick={() => setFilter('all')}
          >
            全期間
          </button>
          <button
            className={`btn ${filter === 'Q1' ? 'btn-active' : ''}`}
            onClick={() => setFilter('Q1')}
          >
            第1四半期 (1-3月)
          </button>
          <button
            className={`btn ${filter === 'Q2' ? 'btn-active' : ''}`}
            onClick={() => setFilter('Q2')}
          >
            第2四半期 (4-6月)
          </button>
        </div>
      </header>

      <div className="card-grid">
        <MetricCard
          title="総売上"
          value={`¥${totalSales.toLocaleString()}`}
          trend="+12.5% 前月比"
          isPositive={true}
        />
        <MetricCard
          title="総客数"
          value={`${totalCustomers.toLocaleString()} 人`}
          trend="+5.2% 前月比"
          isPositive={true}
        />
        <MetricCard
          title="平均単価"
          value={`¥${avgUnitPrice.toLocaleString()}`}
          trend="-1.1% 前月比"
          isPositive={false}
        />
      </div>

      <SalesChart data={filteredData} />
    </div>
  );
}
